/** `accepted` and `duplicate` both mean the event is committed. */
export function isCommitted(outcome: IngestOutcome): boolean {
  return outcome === "accepted" || outcome === "duplicate";
}

/** The sender can delete its queued copy: committed, or deliberately dropped because the source was deleted. */
export function isFinal(outcome: IngestOutcome): boolean {
  return isCommitted(outcome) || outcome === "deleted";
}

