export type AnalysisStatus = z.infer<typeof AnalysisStatusSchema>;

export const AnalyzeResponseSchema = z.object({ status: AnalysisStatusSchema, enqueued: z.number().int().nonnegative() });
export type AnalyzeResponse = z.infer<typeof AnalyzeResponseSchema>;

export const TargetKindSchema = z.enum(["grammar", "vocabulary", "pronunciation"]);
export const TargetLifecycleSchema = z.enum(["active", "improving", "maintained", "archived"]);
export type TargetLifecycle = z.infer<typeof TargetLifecycleSchema>;

export const TargetSchema = z.object({
  id: Id,
  kind: TargetKindSchema,
  /** Canonical, normalized key: a controlled grammar pattern label or word plus sense. */
  key: z.string(),
  description: z.string(),
  lifecycle: TargetLifecycleSchema,
  firstSeenAt: IsoTime.nullable(),
  lastSeenAt: IsoTime.nullable(),
  /** Distinct conversations with a confirmed personal occurrence. Overlapping analysis chunks never inflate this. */
  conversationCount: z.number().int().nonnegative(),
  occurrenceCount: z.number().int().nonnegative(),
  lastPracticedAt: IsoTime.nullable(),
  topics: z.array(z.string()),
  pinned: z.boolean(),
  draftIds: z.array(Id),
});
export type Target = z.infer<typeof TargetSchema>;

export const OccurrenceSchema = z.object({
  findingId: Id,
  conversationId: Id,
  excerpt: z.string(),
  correction: z.string().nullable(),
  confirmedAt: IsoTime,
});
export type Occurrence = z.infer<typeof OccurrenceSchema>;

export const TargetDetailSchema = z.object({ target: TargetSchema, occurrences: z.array(OccurrenceSchema) });
export type TargetDetail = z.infer<typeof TargetDetailSchema>;

export const TargetListResponseSchema = z.object({ targets: z.array(TargetSchema) });
export type TargetListResponse = z.infer<typeof TargetListResponseSchema>;

export const TargetPatchRequestSchema = z
  .object({
    mutationId: Id,
    lifecycle: TargetLifecycleSchema.optional(),
    pinned: z.boolean().optional(),
    topics: z.array(z.string().trim().min(1).max(40)).max(10).optional(),
  })
  .refine((v) => v.lifecycle !== undefined || v.pinned !== undefined || v.topics !== undefined, { message: "Send a change" });
export type TargetPatchRequest = z.infer<typeof TargetPatchRequestSchema>;

/** Reviewable, never automatic: similar targets the learner may want to combine. */
export const MergeSuggestionSchema = z.object({ keepId: Id, mergeId: Id, reason: z.string() });
export const MergeSuggestionsResponseSchema = z.object({ suggestions: z.array(MergeSuggestionSchema) });
export const TargetMergeRequestSchema = z.object({ mutationId: Id, keepId: Id, mergeId: Id });
export type TargetMergeRequest = z.infer<typeof TargetMergeRequestSchema>;

export const SuggestionReasonSchema = z.enum([
  "changes_meaning",
  "two_conversations_30d",
  "repeated_after_practice",
  "broadly_reusable",
  "active_topic_or_marked",
  "naturalness_only",
  "pinned",
]);
export type SuggestionReason = z.infer<typeof SuggestionReasonSchema>;

export const SuggestionSchema = z.object({
  target: TargetSchema,
  score: z.number().int(),
  reasons: z.array(SuggestionReasonSchema),
  /** Cards this suggestion would consume from the daily budget (a note with two templates counts as two). */
  cardCost: z.number().int().positive(),
  existingDraftId: Id.nullable(),
});
export type Suggestion = z.infer<typeof SuggestionSchema>;

export const SuggestionsResponseSchema = z.object({
  date: z.string(),
  budget: z.object({ cards: z.number().int().positive(), usedCards: z.number().int().nonnegative(), remainingCards: z.number().int().nonnegative() }),
  /** Fits the remaining card budget, in ranked order. */
  suggestions: z.array(SuggestionSchema),
  /** The rest, behind View all. */
  more: z.array(SuggestionSchema),
});
export type SuggestionsResponse = z.infer<typeof SuggestionsResponseSchema>;

/** Daily card budget, counted in cards, not notes. */
export const DEFAULT_DAILY_CARD_BUDGET = 5;

// ------------------------------------------ Stage 4: practice and sessions

export const PracticeModeSchema = z.enum(["produce", "read_aloud"]);
export type PracticeMode = z.infer<typeof PracticeModeSchema>;

export const PracticeOutcomeSchema = z.enum(["feedback", "assessment_failed", "cancelled"]);
export type PracticeOutcome = z.infer<typeof PracticeOutcomeSchema>;

/** Provider scores exactly as returned, kept apart from any generated coaching text. */
export const AssessmentEvidenceSchema = z.object({
  provider: z.string().max(60),
  providerVersion: z.string().max(60),
  overall: z.number().nullable(),
  pronunciation: z.number().nullable(),
  tone: z.number().nullable(),
  fluency: z.number().nullable(),
  completeness: z.number().nullable(),
});
export type AssessmentEvidence = z.infer<typeof AssessmentEvidenceSchema>;

export const PracticeAttemptCreateSchema = z.object({
  /** Minted on the phone for each recording; the idempotency key for this attempt. */
  attemptId: Id,
  mode: PracticeModeSchema,
  targetId: Id.nullable().default(null),
  sessionId: Id.nullable().default(null),
  /** The English situation shown first (produce) or the sentence being read (read_aloud). */
  prompt: z.string().trim().min(1).max(500),
  /** The exact Chinese reference used for this attempt; immutable once stored. */
  reference: z.string().trim().min(1).max(500),
  /** True when the Chinese, pinyin or reference audio was shown BEFORE the first attempt (then it is not independent production). */
  answerRevealedBeforeAttempt: z.boolean(),
  /** What the learner actually said or typed, when known. Spontaneous grammar is never inferred from a scripted score. */
  attemptText: z.string().trim().max(500).nullable().default(null),
  attemptTextSource: z.enum(["typed", "self_confirmed", "transcribed"]).nullable().default(null),
  assessment: AssessmentEvidenceSchema.nullable().default(null),
  /** Generated coaching, stored separately from the provider scores. */
  coaching: z.string().max(1000).nullable().default(null),
  feedbackVersion: z.string().max(40).nullable().default(null),
  outcome: PracticeOutcomeSchema,
  /** Corrected retry of an earlier attempt, kept separate from initial attempts. */
  retryOf: Id.nullable().default(null),
  startedAt: IsoTime,
});
export type PracticeAttemptCreate = z.infer<typeof PracticeAttemptCreateSchema>;

export const PracticeAttemptSchema = PracticeAttemptCreateSchema.extend({
  id: Id,
  /** Server-derived: produce mode, answer not revealed first, an actual attempt. A scripted read never counts as unaided production. */
  independent: z.boolean(),
  createdAt: IsoTime,
});
export type PracticeAttempt = z.infer<typeof PracticeAttemptSchema>;

export const PracticeAttemptListSchema = z.object({ attempts: z.array(PracticeAttemptSchema) });

export const SessionKindSchema = z.enum(["grammar", "vocabulary", "pronunciation", "mixed"]);
export const SessionSegmentSchema = z.enum(["revisit", "build", "extend", "consolidate"]);
export type SessionSegment = z.infer<typeof SessionSegmentSchema>;
export const SessionStateSchema = z.enum(["active", "paused", "ended", "abandoned"]);

/** Planned minutes per segment: 3 + 6 + 4 + 2 = the default 15-minute session. A timer is guidance, never an interruption. */
export const SESSION_SEGMENT_MINUTES: Record<SessionSegment, number> = { revisit: 3, build: 6, extend: 4, consolidate: 2 };

export const FocusSessionSchema = z.object({
  id: Id,
  kind: SessionKindSchema,
  topics: z.array(z.string()),
  state: SessionStateSchema,
  segment: SessionSegmentSchema,
  plannedMinutes: z.number().int().positive(),
  startedAt: IsoTime,
  endedAt: IsoTime.nullable(),
  /** Milliseconds spent paused so far. */
  pausedMs: z.number().int().nonnegative(),
  targetIds: z.array(Id),
  acceptedFindingIds: z.array(Id),
  revision: z.number().int().positive(),
});
export type FocusSession = z.infer<typeof FocusSessionSchema>;

export const SessionCreateRequestSchema = z.object({
  mutationId: Id,
  kind: SessionKindSchema.default("mixed"),
  topics: z.array(z.string().trim().min(1).max(40)).max(3).default([]),
  plannedMinutes: z.number().int().min(5).max(60).default(15),
});
export type SessionCreateRequest = z.infer<typeof SessionCreateRequestSchema>;

export const SessionPatchRequestSchema = z
  .object({
    mutationId: Id,
    expectedRevision: z.number().int().positive(),
    action: z.enum(["pause", "resume", "set_segment", "link_target", "accept_finding"]),
    segment: SessionSegmentSchema.optional(),
    targetId: Id.optional(),
    findingId: Id.optional(),
  })
  .refine(
    (v) =>
      (v.action !== "set_segment" || v.segment !== undefined) &&
      (v.action !== "link_target" || v.targetId !== undefined) &&
      (v.action !== "accept_finding" || v.findingId !== undefined),
    { message: "Missing the value this action needs" },
  );
export type SessionPatchRequest = z.infer<typeof SessionPatchRequestSchema>;

export const SessionEndRequestSchema = z.object({
  mutationId: Id,
  /** `end` finishes and prepares drafts; `abandon` keeps attempts and feedback but adds no cards. */
  mode: z.enum(["end", "abandon"]),
});
export type SessionEndRequest = z.infer<typeof SessionEndRequestSchema>;

export const SessionEndResponseSchema = z.object({
  session: FocusSessionSchema,
  /** New useful targets got a draft; repeated ones are linked to their existing card instead. */
  createdDraftIds: z.array(Id),
  linkedExisting: z.array(z.object({ targetId: Id, draftId: Id })),
  remainingCardBudget: z.number().int().nonnegative(),
});
export type SessionEndResponse = z.infer<typeof SessionEndResponseSchema>;
